            new_route = routes[ri] + list(reversed(routes[rj]))
        else:
            continue

        # Create new route_id: choose deterministic smallest old id if possible
        new_id = min(ri, rj)
        old_ids = (ri, rj)
        # Remove old routes
        for oid in old_ids:
            if oid in routes:
                del routes[oid]
            if oid in load:
                del load[oid]
        # Update route lists
        routes[new_id] = new_route
        load[new_id] = load[old_ids[0]] + load[old_ids[1]] if old_ids[0] in (0,) else 0
        # Above line is wrong if using indices; recompute deterministically:
        # (keep it correct and simple)
        lnew = 0
        for c in new_route:
            lnew += demands[c]
        load[new_id] = lnew
        # Update route_ids list
        new_route_ids = []
        for rid in route_ids:
            if rid not in old_ids and rid != new_id:
                new_route_ids.append(rid)
        # Ensure new_id exists exactly once
        if new_id not in new_route_ids:
            new_route_ids.append(new_id)
        route_ids = new_route_ids

        # Update route_of mapping
        for c in new_route:
            route_of[c] = new_id

    # Collect final routes, ensure all customers included
    seen = set()
    final_routes = []
    for rid in list(routes.keys()):
        r = routes[rid]
        if not r:
            continue
        ok = True
        for c in r:
            if c in seen:
                ok = False
                break
            seen.add(c)
        if ok:
            final_routes.append(r)

    # Add any missing customers as new routes
    missing = [c for c in remaining if c not in seen]
    for c in missing:
        final_routes.append([c])

    # --- Intra-route 2-opt local improvement (deterministic) ---
    def route_cost(route):
        if not route:
            return 0
        cost = matrix[depot][route[0]] + matrix[route[-1]][depot]
        for k in range(len(route) - 1):
            cost += matrix[route[k]][route[k + 1]]
        return cost

    def route_feasible(route):
        s = 0
        for c in route:
            s += demands[c]
            if s > capacity:
                return False
        return True

    # Limit improvement passes for runtime
    for _ in range(2):
        improved_any = False
        for ridx in range(len(final_routes)):
            r = final_routes[ridx]
            n = len(r)
            if n <= 3:
                continue
            base = route_cost(r)
            best_delta = 0
            best_i = -1
            best_j = -1
            # Deterministic: first best found in lexicographic order among improvements
            for i in range(n - 1):
                for j in range(i + 1, n):
                    # Reverse segment i..j
                    if i == 0 and j == n - 1:
                        continue
                    new_r = r[:i] + list(reversed(r[i:j + 1])) + r[j + 1:]
                    if not route_feasible(new_r):
                        continue
                    new_c = route_cost(new_r)
                    delta = new_c - base
                    if delta < best_delta:
                        best_delta = delta
                        best_i, best_j = i, j
                        if best_delta < 0:
                            # keep searching to ensure most negative; still deterministic
                            pass
            if best_i != -1:
                final_routes[ridx] = final_routes[ridx][:best_i] + list(
                    reversed(final_routes[ridx][best_i:best_j + 1])
                ) + final_routes[ridx][best_j + 1:]
                improved_any = True
        if not improved_any:
            break

    # --- Inter-route relocate (move one customer) ---
    # Deterministic best-improving within limited candidates
    def feasible_after_move(route_a, route_b, move_idx, insert_pos, from_a_to_b=True):
        # move route_a[move_idx] to route_b at insert_pos
        c = route_a[move_idx]
        if from_a_to_b:
            load_a = sum(demands[x] for x in route_a) - demands[c]
            load_b = sum(demands[x] for x in route_b) + demands[c]
        else:
            load_a = sum(demands[x] for x in route_a) + demands[c]
            load_b = sum(demands[x] for x in route_b) - demands[c]
        if load_a > capacity or load_b > capacity:
            return False
        return True

    def cost_with_route(route):
        return route_cost(route)

    # Precompute costs
    costs = [route_cost(r) for r in final_routes]

    for _ in range(2):
        improved = False
        nr = len(final_routes)
        if nr <= 1:
            break
        # Candidate pairing limited to keep deterministic and fast
        for a in range(nr):
            ra = final_routes[a]
            if not ra:
                continue
            for b in range(nr):
                if a == b or not final_routes[b]:
                    continue
                rb = final_routes[b]
                # Move only boundary customers to reduce work and keep structure
                candidate_indices = [0, len(ra) - 1]
                for mi in candidate_indices:
                    if mi < 0 or mi >= len(ra):
                        continue
                    c = ra[mi]
                    # Try insert positions also boundary/near-boundary
                    insert_positions = [0, 1, len(rb)]
                    if len(rb) >= 2:
                        insert_positions += [len(rb) - 1]
                    insert_positions = sorted(set(insert_positions))
                    for ip in insert_positions:
                        if ip < 0 or ip > len(rb):
                            continue
                        # Build new routes
                        new_ra = ra[:mi] + ra[mi + 1:]
                        new_rb = rb[:ip] + [c] + rb[ip:]
                        if not feasible_after_move(ra, rb, mi, ip, from_a_to_b=True):
                            continue
                        new_cost_a = cost_with_route(new_ra)
                        new_cost_b = cost_with_route(new_rb)
                        if new_cost_a + new_cost_b < costs[a] + costs[b] - 1e-9:
                            final_routes[a] = new_ra
                            final_routes[b] = new_rb
                            costs[a] = new_cost_a
                            costs[b] = new_cost_b
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if improved:
                break
        if not improved:
            break

    # Final cleanup: remove empty routes and ensure no depot
    res = []
    for r in final_routes:
        if r:
            # Ensure no depot and uniqueness
            rr = []
            seen_local = set()
            for c in r:
                if c == depot:
                    continue
                if c not in seen_local:
                    rr.append(c)
                    seen_local.add(c)
            if rr:
                res.append(rr)
    return res
